SELECT * FROM (SELECT e.event_id,'M:'||m.material_id case_id,e.activity,e.timestamp FROM (SELECT 'TOP:'||operation_id event_id,'Heat Treatment Completed' activity,finished_at timestamp,operation_id source_key FROM finishing_operation_history WHERE finished_at IS NOT NULL AND (operation_code='HT')) e JOIN finishing_operation_history s ON s.operation_id=e.source_key JOIN plate_material piece ON piece.plate_id=s.plate_id JOIN as_rolled_material m ON m.material_id=piece.mother_material_id UNION ALL SELECT e.event_id,'M:'||m.material_id case_id,e.activity,e.timestamp FROM (SELECT 'TOP:'||operation_id event_id,'Surface Finishing Completed' activity,finished_at timestamp,operation_id source_key FROM finishing_operation_history WHERE finished_at IS NOT NULL AND (operation_code='SF')) e JOIN finishing_operation_history s ON s.operation_id=e.source_key JOIN plate_material piece ON piece.plate_id=s.plate_id JOIN as_rolled_material m ON m.material_id=piece.mother_material_id UNION ALL SELECT e.event_id,'M:'||m.material_id case_id,e.activity,e.timestamp FROM (SELECT 'DIM:'||inspection_id event_id,'Dimensional Inspection Completed' activity,inspected_at timestamp,inspection_id source_key FROM dimension_inspection WHERE inspected_at IS NOT NULL AND (1=1)) e JOIN dimension_inspection s ON s.inspection_id=e.source_key JOIN plate_material piece ON piece.plate_id=s.plate_id JOIN as_rolled_material m ON m.material_id=piece.mother_material_id) ORDER BY case_id,timestamp,event_id;
